/* Load figma-helpers.js first. HANDOFF_EXPECTED is embedded below from the input
 * manifest by packaging; it contains original, exact root fingerprints.
 * Invoke runStarwardHandoff({observedUrl}) with a freshly observed browser URL.
 * No browser access, page recreation, component edits, or detach operations. */
var runStarwardHandoff = async function ({observedUrl, download = true}) {
  StarwardFigma.attestBrowserFile({observedUrl, expectedFileKey: HANDOFF_EXPECTED.fileKey,
    documentName: HANDOFF_EXPECTED.documentName, pageId: HANDOFF_EXPECTED.pageId});
  StarwardFigma.requireFile(HANDOFF_EXPECTED.fileKey);
  const assert = (value, message) => { if (!value) throw Error(message); };
  const near = (a,b) => Math.abs(a-b)<0.05;
  const mapSpec = HANDOFF_EXPECTED.boards.find(b => b.page === 'map');
  const mySpec = HANDOFF_EXPECTED.boards.find(b => b.page === 'my');
  const map = await figma.getNodeByIdAsync(mapSpec.rootId);
  const my = await figma.getNodeByIdAsync(mySpec.rootId);
  assert(map && my, 'Missing original roots');
  assert(StarwardFigma.fingerprint(map) === mapSpec.fingerprint, 'Map changed since handoff');
  assert(StarwardFigma.fingerprint(my) === mySpec.fingerprint, 'My changed since handoff');
  const ids = ['1:5209','1:5226','1:5236','1:5237','1:5244','1:5251','1:5253','1:5232','1:5296','1:5247','1:5250'];
  const nodes = await Promise.all(ids.map(id => figma.getNodeByIdAsync(id)));
  assert(nodes.every(Boolean), 'Required actual node missing');
  const [content, utility, contribution, heading, status, arrow, routine, styleSource, nav, draft, review] = nodes;
  assert(content.parent===my && utility.parent===content && contribution.parent===utility &&
    heading.parent===contribution && status.parent===contribution && arrow.parent===contribution &&
    routine.parent===content, 'Unexpected editing scope');
  for (const node of [content,utility,contribution]) {
    assert(node.type==='FRAME' && node.layoutMode==='VERTICAL', 'Expected ordinary Auto Layout frame');
    for(let parent=node; parent && parent!==figma.currentPage; parent=parent.parent)
      assert(parent.type!=='INSTANCE' && parent.type!=='COMPONENT' && parent.type!=='COMPONENT_SET', 'Scope entered a component or instance');
  }
  assert(contribution.children.length===3 && contribution.children[0]===heading &&
    contribution.children[1]===status && arrow.layoutPositioning==='ABSOLUTE', 'Unexpected contribution children or arrow layout');
  assert(draft.characters==='1 条' && review.characters==='2 条', 'Original status values changed');
  assert(styleSource.type==='TEXT' && styleSource.fontSize===14 && styleSource.lineHeight.value===21,
    'Expected existing secondary text style');
  // Read real instance origins before editing. They and all component masters are
  // protected by the complete root comparisons; no override/detach is necessary.
  const instances = my.findAll(n => n.type==='INSTANCE');
  const instanceInventory = await Promise.all(instances.map(async n => {
    const main = await n.getMainComponentAsync();
    assert(main, 'Unresolvable component instance');
    return {id:n.id,mainComponentId:main.id,policy:'preserve instance and main component unchanged'};
  }));
  await figma.loadFontAsync(styleSource.fontName);
  // All awaited preflight work precedes the final original-state check.
  assert(StarwardFigma.fingerprint(map)===mapSpec.fingerprint && StarwardFigma.fingerprint(my)===mySpec.fingerprint,
    'Canvas changed during preflight');
  const before = JSON.parse(mySpec.fingerprint);
  const frames = [contribution,utility,content];
  const savedFrames = frames.map(n => ({n,width:n.width,height:n.height,mode:n.primaryAxisSizingMode}));
  let description = null;
  let metrics;
  const protectedMy = (tree, insertedId) => {
    const visit = n => {
      if(n.id===insertedId) return null;
      // These are the only expected existing-node geometry changes.
      if(['1:5236','1:5226','1:5209'].includes(n.id)) delete n.height;
      if(['1:5244','1:5253'].includes(n.id)) delete n.y;
      if(n.children) n.children=n.children.map(visit).filter(Boolean);
      return n;
    };
    return JSON.stringify(visit(tree));
  };
  try {
    description=figma.createText();
    description.name='Contribution description';
    description.fontName=styleSource.fontName;
    description.fontSize=styleSource.fontSize;
    description.lineHeight=styleSource.lineHeight;
    description.letterSpacing=styleSource.letterSpacing;
    description.fills=styleSource.fills;
    description.textAlignHorizontal='LEFT';
    description.characters='记录现场天气、通行条件与设施变化；补充照片和说明，提交后可以继续查看草稿与审核状态。';
    description.resize(contribution.width-contribution.paddingLeft-contribution.paddingRight,21);
    description.textAutoResize='HEIGHT';
    contribution.insertChild(1,description);
    description.layoutSizingHorizontal='FILL';
    description.layoutSizingVertical='HUG';
    frames.forEach(n => { if(n.primaryAxisSizingMode!=='AUTO') n.primaryAxisSizingMode='AUTO'; });
    // Snapshot awaits provide a stable Plugin API read after layout calculation.
    await StarwardFigma.snapshot(my,{fileKey:HANDOFF_EXPECTED.fileKey,revision:'handoff-layout-check'});
    assert(near(description.width,326) && description.textAutoResize==='HEIGHT', 'Description width or wrap mode changed');
    assert(description.height>=42 && description.height<=84 && near(description.height/21,Math.round(description.height/21)),
      'Unexpected line count; inspect layout before exporting');
    assert(near(description.y,heading.y+heading.height+8) && near(status.y,description.y+description.height+8),
      'Description/status spacing incorrect');
    assert(near(contribution.height,status.y+status.height+14), 'Contribution failed to grow');
    assert(near(routine.y,utility.y+utility.height+20), 'Routine content compressed or overlapping');
    assert(content.y+routine.y+routine.height<=nav.y-16, 'Following content collides with bottom navigation');
    assert(StarwardFigma.fingerprint(map)===mapSpec.fingerprint, 'Protected Map changed');
    assert(protectedMy(JSON.parse(StarwardFigma.fingerprint(my)),description.id)===protectedMy(before,null),
      'My changed outside the allowed insertion and Auto Layout displacement');
    metrics={descriptionId:description.id,width:description.width,height:description.height,
      lines:Math.round(description.height/21),contributionHeight:contribution.height,
      statusY:status.y,routineY:routine.y,contentHeight:content.height,
      contentToNavigationGap:nav.y-(content.y+routine.y+routine.height)};
  } catch(error) {
    if(description && !description.removed) description.remove();
    // Reversible local insertion: restore the original sizing modes and sizes.
    for(const saved of savedFrames) {
      saved.n.primaryAxisSizingMode=saved.mode;
      if(!near(saved.n.width,saved.width)||!near(saved.n.height,saved.height)) saved.n.resize(saved.width,saved.height);
      saved.n.primaryAxisSizingMode=saved.mode;
    }
    throw error;
  }
  const revision='handoff-long-contribution-description';
  const myExport=await StarwardFigma.exportBoard(my,{fileKey:HANDOFF_EXPECTED.fileKey,revision,scale:1});
  const mapExport=await StarwardFigma.exportBoard(map,{fileKey:HANDOFF_EXPECTED.fileKey,revision,scale:1});
  assert(mapExport.fingerprint===mapSpec.fingerprint, 'Map changed during export');
  assert(StarwardFigma.fingerprint(my)===myExport.fingerprint, 'My changed between exports');
  const report={revision,fileKey:HANDOFF_EXPECTED.fileKey,roots:{my:my.id,map:map.id},
    metrics,instanceInventory,checks:{exactOriginalRoots:true,mapFingerprintUnchanged:true,
      myExistingNodesRestrictedDiff:true,unchangedDraftAndReview:true,geometryNoOverlap:true},
    unverified:['Post-export visual inspection by the executing task','Actual phone reading','Touch gestures','Other viewport widths','Production WEAPP conformance']};
  const files=[{name:'handoff-my.json',data:JSON.stringify(myExport.structure,null,2)},
    {name:'handoff-my.png',data:myExport.png},
    {name:'handoff-map.json',data:JSON.stringify(mapExport.structure,null,2)},
    {name:'handoff-map.png',data:mapExport.png},
    {name:'handoff-checks.json',data:JSON.stringify(report,null,2)},
    {name:'handoff-fingerprints.json',data:JSON.stringify({my:myExport.fingerprint,map:mapExport.fingerprint},null,2)}];
  if(download) { assert(typeof starwardDownload==='function','Load scripter-export.js to download'); await starwardDownload(files); }
  return {report,files};
};


await runStarwardHandoff({observedUrl:"https://www.figma.com/design/tU01DsKBhSng9IHk1xlJQA/Starward-%E5%9C%B0%E5%9B%BE%E4%B8%8E%E6%88%91%E7%9A%84-%C2%B7-%E8%AE%BE%E8%AE%A1%E8%B5%84%E6%BA%90?node-id=1-58&t=k10Psqjzmb8PP4XP-0"});